const fs=require("fs");
let css=fs.readFileSync("fonts.css","utf8");
// split blocks; keep latin only
const blocks=css.split("/*").map(b=>"/*"+b);
let out=[]; let n=0;
for(const b of blocks){
 if(!b.includes("@font-face")) continue;
 if(!b.startsWith("/* latin */")) continue;
 const m=b.match(/font-family: \x27([^\x27]+)\x27/); const w=b.match(/font-weight: (\d+)/); const u=b.match(/url\((https:[^)]+)\)/);
 if(!u) continue;
 const name=`${m[1].replace(/ /g,"-").toLowerCase()}-${w[1]}.woff2`;
 out.push({name,url:u[1]});
 css=b.replace(u[1],name);
 fs.appendFileSync("local.css",css+"\n");
}
fs.writeFileSync("dl.json",JSON.stringify(out));
console.log(out.map(o=>o.name).join("\n"));
'

