.edition-tags{display:flex;gap:5px;margin-top:10px}
.edition-tags span{font-size:7px;font-weight:800;letter-spacing:.12em;padding:4px 6px;border:1px solid var(--line);border-radius:3px;color:#aebfc2;background:rgba(255,255,255,.04)}
.side-stats{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.1);border-radius:9px;overflow:hidden}
.side-stats div{background:rgba(5,13,18,.86);padding:9px 12px;display:flex;flex-direction:column;gap:2px}
.side-stats small{font-size:7px;letter-spacing:.2em;color:#7f969a;font-weight:800}
