.foot-badges span{font-size:7px;font-weight:800;letter-spacing:.14em;color:#9db0b3;border:1px solid var(--line);padding:3px 6px;border-radius:3px}
.foot-copy{font-size:8px;color:#51676b;letter-spacing:.04em}

/* ============================================================
   HUD
   ============================================================ */
#hud{position:absolute;inset:0;z-index:25;pointer-events:none;font-size:calc(1px * var(--hud-scale))}
#hud button{pointer-events:auto}
.hud-top-left{position:absolute;top:18px;left:20px;display:flex;flex-direction:column;align-items:flex-start;gap:7px;transform-origin:top left;transform:scale(var(--hud-scale))}
.wanted-row{display:flex;flex-direction:column;align-items:flex-end;align-self:flex-end;margin-right:2px;gap:2px}
.wanted-stars{display:flex;gap:2px;filter:drop-shadow(0 2px 6px rgba(0,0,0,.8))}
.wanted-stars svg{width:15px;height:15px;fill:rgba(255,255,255,.12);stroke:rgba(255,255,255,.25);stroke-width:1;transition:.25s}
.wanted-stars svg.on{fill:var(--gold);stroke:#ffe1a3;filter:drop-shadow(0 0 6px rgba(255,196,107,.75))}
.wanted-stars svg.hot{fill:var(--red);stroke:#ffb3ba;animation:starFlash .55s infinite alternate}
@keyframes starFlash{from{opacity:1;transform:scale(1)}to{opacity:.55;transform:scale(1.12)}}
.wanted-label{font-size:6.5px;letter-spacing:.24em;font-weight:800;color:#ffd28d;opacity:0;transition:.25s}
.wanted-label.on{opacity:1}
.minimap-wrap{position:relative;width:184px;height:184px;border-radius:50%;transition:.25s}
.minimap-wrap canvas{width:100%;height:100%;border-radius:50%;display:block;background:#0b2831;box-shadow:0 8px 30px rgba(0,0,0,.6),inset 0 0 0 1px rgba(255,255,255,.2)}
.minimap-ring{position:absolute;inset:-3px;border-radius:50%;border:2px solid rgba(255,255,255,.55);box-shadow:0 0 0 3px rgba(3,10,14,.55),0 0 24px rgba(0,0,0,.4);pointer-events:none}
.minimap-ring:before{content:"";position:absolute;inset:-7px;border-radius:50%;border:1px solid rgba(255,196,107,.35)}
.minimap-district{position:absolute;bottom:-4px;left:50%;transform:translateX(-50%);padding:3px 10px;background:rgba(3,10,14,.85);border:1px solid rgba(255,255,255,.18);border-radius:20px;font-size:6.5px;font-weight:800;letter-spacing:.2em;color:#e6d2ae;white-space:nowrap;backdrop-filter:blur(5px)}
.minimap-expand{position:absolute;right:-5px;bottom:16px;width:25px;height:25px;border-radius:50%;background:rgba(3,10,14,.9);border:1px solid rgba(255,255,255,.25);display:grid;place-items:center;color:#dce8e9;transition:.15s}
.minimap-expand:hover{background:var(--gold);color:#20130a;transform:scale(1.08)}
.minimap-expand svg{width:13px;height:13px}
.minimap-north{position:absolute;top:-13px;left:50%;transform:translateX(-50%);font-family:var(--font-display);font-weight:800;font-size:11px;color:#fff;text-shadow:0 1px 4px #000}
.cash-row{display:flex;align-items:baseline;gap:5px;margin-top:8px;text-shadow:0 2px 8px rgba(0,0,0,.9)}
