.compass-marker.on{opacity:1}

.hud-top-right{position:absolute;top:18px;right:20px;display:flex;flex-direction:column;align-items:flex-end;gap:7px;transform-origin:top right;transform:scale(var(--hud-scale))}
.objective-panel{width:238px;padding:11px 13px 10px;background:linear-gradient(180deg,rgba(8,19,26,.9),rgba(6,15,21,.78));border:1px solid rgba(255,255,255,.13);border-left:2px solid var(--gold);border-radius:6px;box-shadow:0 10px 30px rgba(0,0,0,.4);backdrop-filter:blur(8px)}
.obj-kicker{font-size:6.5px;font-weight:800;letter-spacing:.24em;color:var(--gold);margin-bottom:4px}
.obj-title{font-family:var(--font-display);font-size:19px;font-weight:700;line-height:1.05;letter-spacing:.02em}
