.mission-clock{display:flex;align-items:baseline;gap:7px;background:rgba(3,10,14,.78);border:1px solid rgba(255,255,255,.12);border-radius:5px;padding:5px 9px;backdrop-filter:blur(5px)}
.mission-clock span{font-size:6px;letter-spacing:.2em;color:#9fb2b4;font-weight:800}
.mission-clock b{font-family:var(--font-display);font-size:16px;color:var(--gold);letter-spacing:.08em}
.rp-panel-mini{width:238px;padding:8px 11px;background:rgba(8,19,26,.82);border:1px solid rgba(46,230,200,.25);border-radius:5px;font-size:8px;color:#a8c6c5;backdrop-filter:blur(6px)}
