.rp-mini-bar i{display:block;height:100%;width:0;background:var(--teal);transition:width .3s}

.hud-bottom-left{position:absolute;bottom:20px;left:20px;display:flex;flex-direction:column;gap:7px;transform-origin:bottom left;transform:scale(var(--hud-scale))}
.char-badge{display:flex;align-items:center;gap:9px;padding:6px 10px 6px 6px;background:linear-gradient(90deg,rgba(5,14,19,.92),rgba(5,14,19,.55));border:1px solid rgba(255,255,255,.12);border-radius:8px;backdrop-filter:blur(7px)}
.char-portrait{width:40px;height:44px;border-radius:5px;overflow:hidden;background:#0d222a;border:1px solid rgba(255,255,255,.15)}
