396: function buildCarMesh(type, color, name) {
397:   const g = new THREE.Group();
398:   const wheels = [];
399:   const mats = [];
400:   const mat = (c, r = 0.42, m = 0.2) => { const mm = new THREE.MeshStandardMaterial({ color: c, roughness: r, metalness: m }); mats.push(mm); return mm; };
401:   const bodyMat = mat(color, 0.34, 0.35);
402:   const darkMat = mat(0x131a1e, 0.5, 0.3);
403:   const glassMat = mat(0x17303a, 0.12, 0.55);
404:   const lightMat = new THREE.MeshStandardMaterial({ color: 0xfff2c8, emissive: 0xffe0a0, emissiveIntensity: 0.8, roughness: 0.3 });
405:   const tailMat = new THREE.MeshStandardMaterial({ color: 0xff3b2f, emissive: 0xaa1100, emissiveIntensity: 0.7, roughness: 0.4 });
406: 
407:   let L = 4.4, W = 1.9, H = 0.62;
408:   if (type === 'sports') { L = 4.5; W = 2.0; H = 0.48; }
409:   if (type === 'suv') { L = 4.7; W = 2.0; H = 0.8; }
410:   if (type === 'pickup') { L = 5.0; W = 2.0; H = 0.72; }
411:   if (type === 'taxi') { L = 4.4; W = 1.9; H = 0.62; }
412:   if (type === 'police') { L = 4.6; W = 1.95; H = 0.64; }
413: 
414:   const body = new THREE.Mesh(new THREE.BoxGeometry(W, H, L), bodyMat);
415:   body.position.y = 0.52 + H / 2; g.add(body);
416:   const hood = new THREE.Mesh(new THREE.BoxGeometry(W * 0.94, 0.14, L * 0.3), bodyMat);
417:   hood.position.set(0, 0.58 + H, L * 0.33); g.add(hood);
418:   const cabin = new THREE.Mesh(new THREE.BoxGeometry(W * 0.82, 0.56, L * (type === 'pickup' ? 0.3 : 0.42)), glassMat);
419:   cabin.position.set(0, 0.58 + H + 0.27, type === 'pickup' ? L * 0.14 : -L * 0.02);
420:   g.add(cabin);
421:   const roof = new THREE.Mesh(new THREE.BoxGeometry(W * 0.84, 0.09, L * (type === 'pickup' ? 0.31 : 0.4)), bodyMat);
422:   roof.position.set(0, 0.58 + H + 0.56, cabin.position.z); g.add(roof);
423: 
424:   if (type === 'pickup') {
425:     const bed = new THREE.Mesh(new THREE.BoxGeometry(W * 0.92, 0.25, L * 0.32), darkMat);
426:     bed.position.set(0, 0.58 + H + 0.12, -L * 0.29); g.add(bed);
427:   }
428:   if (type === 'taxi') {
429:     const sign = new THREE.Mesh(new THREE.BoxGeometry(0.7, 0.22, 0.3), new THREE.MeshStandardMaterial({ color: 0xffd166, emissive: 0xffc46b, emissiveIntensity: 0.5 }));
430:     sign.position.set(0, 0.58 + H + 0.7, -L * 0.02); g.add(sign);
431:   }
432:   if (type === 'police') {
433:     const bar = new THREE.Mesh(new THREE.BoxGeometry(W * 0.7, 0.16, 0.32), darkMat);
434:     bar.position.set(0, 0.58 + H + 0.68, -L * 0.02); g.add(bar);
435:     const red = new THREE.Mesh(new THREE.BoxGeometry(W * 0.3, 0.13, 0.28), new THREE.MeshStandardMaterial({ color: 0xff2d3d, emissive: 0xff1122, emissiveIntensity: 2 }));
436:     red.position.set(-W * 0.18, 0.58 + H + 0.78, -L * 0.02); g.add(red);
437:     const blue = new THREE.Mesh(new THREE.BoxGeometry(W * 0.3, 0.13, 0.28), new THREE.MeshStandardMaterial({ color: 0x2d7dff, emissive: 0x1155ff, emissiveIntensity: 2 }));
438:     blue.position.set(W * 0.18, 0.58 + H + 0.78, -L * 0.02); g.add(blue);
439:     g.userData.lightRed = red; g.userData.lightBlue = blue;
440:     const stripe = new THREE.Mesh(new THREE.BoxGeometry(W * 1.01, 0.2, L * 0.34), mat(0xf2efe4, 0.5));
441:     stripe.position.set(0, 0.58 + H * 0.55, 0); g.add(stripe);
442:   }
443: 
444:   // lights
445:   for (const x of [-W * 0.32, W * 0.32]) {
446:     const hl = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.16, 0.08), lightMat);
447:     hl.position.set(x, 0.64 + H * 0.5, L / 2 + 0.01); g.add(hl);
448:     const tl = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.14, 0.08), tailMat);
449:     tl.position.set(x, 0.64 + H * 0.5, -L / 2 - 0.01); g.add(tl);
450:   }
451:   // wheels
452:   const wheelGeo = new THREE.CylinderGeometry(0.37, 0.37, 0.24, 10);
453:   wheelGeo.rotateZ(Math.PI / 2);
454:   const wheelMat = mat(0x121619, 0.85, 0.1);
455:   for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
456:     const wh = new THREE.Mesh(wheelGeo, wheelMat);
457:     wh.position.set(sx * (W / 2 - 0.06), 0.37, sz * (L * 0.32));
458:     g.add(wh); wheels.push(wh);
459:     const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.26, 8), mat(0x9aa4a6, 0.3, 0.8));
460:     hub.rotation.z = Math.PI / 2;
461:     hub.position.copy(wh.position); g.add(hub);
462:   }
463:   // shadow
464:   const shadow = new THREE.Mesh(new THREE.PlaneGeometry(W + 0.8, L + 0.6), new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 0.28, depthWrite: false }));
465:   shadow.rotation.x = -Math.PI / 2; shadow.position.y = 0.03; g.add(shadow);
466:   // bumpers
467:   const bump = new THREE.Mesh(new THREE.BoxGeometry(W * 0.98, 0.16, 0.16), darkMat);
468:   bump.position.set(0, 0.45, L / 2 + 0.06); g.add(bump);
469:   const bump2 = bump.clone(); bump2.position.z = -L / 2 - 0.06; g.add(bump2);
470: 
471:   g.userData.wheels = wheels;
472:   g.userData.bodyMat = bodyMat;
473:   g.userData.mats = mats;
474:   g.userData.lights = { head: lightMat, tail: tailMat };
475:   g.userData.name = name || type;
476:   return g;
477: }
