494:   const glass = new THREE.Mesh(new THREE.BoxGeometry(2.36, 0.55, 2.66), dark);
495:   glass.position.set(0, 2.35, -1.2); g.add(glass);
496:   const motor = new THREE.Mesh(new THREE.BoxGeometry(0.8, 1.1, 1.1), dark);
