import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/shots';
mkdirSync(out, { recursive: true });
const LOW = { quality: 'medium', resScale: 60, shadows: false, water: 'low', distance: 60, showFps: true };
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(90000);
await page.addInitScript((s) => { localStorage.setItem('matteo5.settings.v1', JSON.stringify(s)); localStorage.removeItem('matteo5.save.v1'); }, LOW);
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
await page.locator('[data-menu="play"]').click();
await page.waitForTimeout(300);
await page.locator('.cs-card.luiza').click();
await page.waitForTimeout(2200);
await page.locator('#tut-start').click().catch(()=>{});
await page.waitForTimeout(1000);
const info = await page.evaluate(() => {
  const g = window.__game;
  const c = g.camera, p = g.player;
  const dir = new c.position.constructor(); c.getWorldDirection(dir);
  return {
    mode: g.mode,
    player: { x: p.pos.x, y: p.pos.y, z: p.pos.z, yaw: p.yaw },
    camera: { x: c.position.x, y: c.position.y, z: c.position.z, fov: c.fov },
    dir: { x: dir.x, y: dir.y, z: dir.z },
    camYaw: g._camYaw, camPitch: g._camPitch, camDist: g._camDist,
    blockedCam: g.world.pointBlocked(c.position.x, c.position.y, c.position.z, 0.3),
    near: g.world._nearColliders ? g.world._nearColliders(c.position.x, c.position.z).map(x=>({minX:x.minX,maxX:x.maxX,minZ:x.minZ,maxZ:x.maxZ,h:x.h,type:x.type})) : null,
    ground: g.world.groundHeight(p.pos.x, p.pos.z),
    district: g.world.districtAt(p.pos.x,p.pos.z),
    fps: g.fps
  };
});
console.log(JSON.stringify(info, null, 2));
await page.screenshot({ path: `${out}/probe-spawn.png` });
// look from above
await page.evaluate(() => { const g=window.__game; g.camera.position.set(g.player.pos.x+10, 25, g.player.pos.z+10); g.camera.lookAt(g.player.pos.x, 0, g.player.pos.z); });
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/probe-above.png` });
await browser.close();

