        vWorld = wp.xyz;
        float dx = cos(wp.x*0.055+t*1.05)*0.055*0.38
                 + cos((wp.x+wp.z)*0.032+t*0.58)*0.032*0.5
                 + cos((wp.x-wp.z)*0.115+t*1.5)*0.115*0.08;
        float dz = cos(wp.z*0.082-t*0.82)*0.082*0.24
                 + cos((wp.x+wp.z)*0.032+t*0.58)*0.032*0.5
