import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/shots2';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.setDefaultTimeout(90000);
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0,800)); });
await page.addInitScript(() => { localStorage.setItem('matteo5.settings.v1', JSON.stringify({ quality:'medium', resScale:70, shadows:false, water:'high', distance:80, showFps:true })); localStorage.removeItem('matteo5.save.v1'); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
await page.locator('[data-menu="play"]').click();
await page.waitForTimeout(300);
await page.locator('.cs-card.luiza').click();
await page.waitForTimeout(2400);
await page.locator('#tut-start').click().catch(()=>{});
await page.waitForTimeout(800);
console.log('water info', await page.evaluate(() => {
  const g = window.__game, w = g.world;
  return {
    player: { x: g.player.pos.x, y: g.player.pos.y, z: g.player.pos.z },
    cam: { x: g.camera.position.x, y: g.camera.position.y, z: g.camera.position.z },
    water: { pos: { x: w.water.position.x, y: w.water.position.y, z: w.water.position.z }, visible: w.water.visible, mat: w.water.material.type, uniforms: Object.keys(w.waterUniforms), seg: w.water.geometry.parameters },
    shore: 700, ground: w.groundHeight(690,10), isWater: w.isWater(710,10)
  };
}));
// Teleport to shore
await page.evaluate(() => {
  const g = window.__game;
  g.player.pos.set(680, 0, 10); g.player.yaw = Math.PI/2; g._camYaw = Math.PI/2; g._camPitch = 0.18;
  g._placePlayer(); g._snapCamera();
});
await page.waitForTimeout(1500);
console.log('after teleport', await page.evaluate(() => { const g=window.__game; return { p:{x:g.player.pos.x,z:g.player.pos.z}, cam:{x:+g.camera.position.x.toFixed(1),y:+g.camera.position.y.toFixed(1),z:+g.camera.position.z.toFixed(1)}, pitch:g._camPitch }; }));
await page.screenshot({ path: `${out}/water-shore.png` });
// High view
await page.evaluate(() => {
  const g = window.__game;
  g.camera.position.set(640, 35, 10);
  g.camera.lookAt(900, -1, 10);
});
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/water-high.png` });
// top down
await page.evaluate(() => {
  const g = window.__game;
  g.camera.position.set(760, 140, 10);
  g.camera.lookAt(760, -1, 10);
});
await page.waitForTimeout(500);
await page.screenshot({ path: `${out}/water-top.png` });
await browser.close();

