import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/shots2';
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 900, height: 600 } });
page.setDefaultTimeout(90000);
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0,1000)); });
await page.addInitScript(() => { localStorage.setItem('matteo5.settings.v1', JSON.stringify({ quality:'low', resScale:60, shadows:false, water:'low', distance:60, showFps:false })); localStorage.removeItem('matteo5.save.v1'); });
await page.goto('http://127.0.0.1:4173/', { waitUntil: 'load' });
await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
await page.locator('[data-menu="play"]').click();
await page.waitForTimeout(300);
await page.locator('.cs-card.luiza').click();
await page.waitForTimeout(2200);
await page.locator('#tut-start').click().catch(()=>{});
await page.waitForTimeout(600);
console.log('uniforms', await page.evaluate(() => {
  const u = window.__game.world.waterUniforms;
  const c = (x) => x.value && x.value.getHexString ? '#'+x.value.getHexString() : x.value;
  return { deep:c(u.uDeep), shallow:c(u.uShallow), foam:c(u.uFoam), fog:c(u.uFog), skyTop:c(u.uSkyTop), skyHorizon:c(u.uSkyHorizon), sun:c(u.uSunColor), night:u.uNight.value, shore:u.uShoreX.value, detail:u.uDetail.value };
}));
await page.evaluate(() => {
  const g = window.__game;
  g.camera.position.set(640, 35, 10); g.camera.lookAt(900, -1, 10);
});
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/dbg-normal.png` });
// force red fragment
await page.evaluate(() => {
  const m = window.__game.world.water.material;
  m.fragmentShader = 'void main(){ gl_FragColor = vec4(1.0, 0.0, 0.0, 1.0); }';
  m.needsUpdate = true;
});
await page.waitForTimeout(600);
await page.screenshot({ path: `${out}/dbg-red.png` });
// restore-like: output deep color
await page.evaluate(() => {
  const m = window.__game.world.water.material;
  m.fragmentShader = 'uniform vec3 uDeep; void main(){ gl_FragColor = vec4(uDeep, 1.0); }';
  m.needsUpdate = true;
});
await page.waitForTimeout(600);
await page.screenshot({ path: `${out}/dbg-deep.png` });
await browser.close();

