                * smoothstep(0.58, 0.92, fbm(q * 0.62 + vec2(uTime * 0.7, uTime * 0.3)))
                * 0.16;
float foam = clamp(foamShore + crestFoam, 0.0, 1.0);
col = mix(col, uFoam, foam * 0.82);

