import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/final';
mkdirSync(out, { recursive: true });
const URL = 'http://127.0.0.1:4173/';
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });

function attach(page, tag) {
  page.setDefaultTimeout(90000);
  page.on('pageerror', e => console.log(`[${tag}] PAGEERROR`, e.message));
  page.on('console', m => { if (m.type() === 'error') console.log(`[${tag}] ERROR`, m.text().slice(0, 400)); });
}
async function boot(page, settings, char = 'luiza') {
  await page.addInitScript((s) => {
    localStorage.setItem('matteo5.settings.v1', JSON.stringify(s));
    localStorage.removeItem('matteo5.save.v1');
  }, settings);
  await page.goto(URL, { waitUntil: 'load' });
  await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
  await page.locator('[data-menu="play"]').click();
  await page.waitForTimeout(250);
  await page.locator(`.cs-card.${char}`).click();
  await page.waitForTimeout(2400);
  await page.locator('#tut-start').click().catch(() => {});
  await page.waitForTimeout(800);
}
const ok = (name, cond, extra = '') => console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

// ================= DESKTOP =================
const d = await browser.newPage({ viewport: { width: 1440, height: 900 } });
attach(d, 'desktop');
await boot(d, { quality: 'high', resScale: 90, shadows: true, water: 'high', distance: 85, showFps: true, touch: 'off' });

// --- pointer lock camera ---
await d.mouse.click(720, 470);
await d.waitForTimeout(500);
const lock = await d.evaluate(() => document.pointerLockElement === window.__game.canvas);
ok('pointer lock acquired', lock);
const camTest = await d.evaluate(() => {
  const g = window.__game;
  const y0 = g._camYaw, p0 = g._camPitch;
  g._lockGrace = performance.now() + 320;
  window.dispatchEvent(new MouseEvent('mousemove', { movementX: 900, movementY: 700 }));
  const during = { dy: +(g._camYaw - y0).toFixed(4), dp: +(g._camPitch - p0).toFixed(4) };
  return { y0, p0, during };
});
ok('synthetic lock move ignored', Math.abs(camTest.during.dy) < 1e-6 && Math.abs(camTest.during.dp) < 1e-6, JSON.stringify(camTest.during));
await d.waitForTimeout(380);
const camTest2 = await d.evaluate(() => {
  const g = window.__game;
  const y0 = g._camYaw;
  window.dispatchEvent(new MouseEvent('mousemove', { movementX: 40, movementY: 0 }));
  return +(g._camYaw - y0).toFixed(4);
});
ok('real mouse move turns camera', Math.abs(camTest2) > 0.02, `dy=${camTest2}`);
const camTest3 = await d.evaluate(() => {
  const g = window.__game;
  const y0 = g._camYaw;
  window.dispatchEvent(new MouseEvent('mousemove', { movementX: 900, movementY: 0 }));
  return +(g._camYaw - y0).toFixed(4);
});
ok('outlier delta rejected', Math.abs(camTest3) < 1e-6, `dy=${camTest3}`);

// --- pause + settings above pause ---
await d.keyboard.press('Escape');
await d.waitForTimeout(400);
ok('pause opens', await d.locator('#pause-menu:not(.hidden)').count() === 1);
await d.locator('[data-pause="settings"]').click();
await d.waitForTimeout(350);
const settingsZ = await d.evaluate(() => {
  const s = document.getElementById('settings-modal');
  const p = document.getElementById('pause-menu');
  return { settingsOpen: !s.classList.contains('hidden'), zS: +getComputedStyle(s).zIndex, zP: +getComputedStyle(p).zIndex };
});
ok('settings opens above pause', settingsZ.settingsOpen && settingsZ.zS > settingsZ.zP, JSON.stringify(settingsZ));
await d.locator('#settings-tabs [data-tab="interface"]').click();
await d.waitForTimeout(200);
await d.locator('#set-minimap').selectOption('large');
await d.waitForTimeout(400);
const mmSize = await d.evaluate(() => getComputedStyle(document.getElementById('minimap-wrap')).getPropertyValue('--mm-size').trim());
ok('minimap size setting applies', mmSize === '218px', mmSize);
await d.locator('#set-minimap').selectOption('normal');
await d.locator('#settings-modal [data-close="settings-modal"]').first().click();
await d.waitForTimeout(350);
ok('pause survives closing settings', await d.locator('#pause-menu:not(.hidden)').count() === 1);
await d.screenshot({ path: `${out}/desktop-pause.png` });
await d.locator('[data-pause="resume"]').click();
await d.waitForTimeout(400);
ok('resume closes pause', await d.locator('#pause-menu.hidden').count() === 1);

// --- map ---
await d.keyboard.press('KeyM');
await d.waitForTimeout(500);
const mapInfo = await d.evaluate(() => ({
  open: window.__game.mapOpen,
  zoom: document.getElementById('map-zoom-level').textContent,
  marker: getComputedStyle(document.getElementById('map-player')).display,
  route: !!window.__game._objectivePos,
  canv: [document.getElementById('fullmap').width, document.getElementById('fullmap').height]
}));
ok('map opens with marker + route', mapInfo.open && mapInfo.marker === 'block' && mapInfo.route, JSON.stringify(mapInfo));
await d.screenshot({ path: `${out}/desktop-map.png` });
await d.locator('#map-zoom-in').click();
await d.locator('#map-zoom-in').click();
await d.waitForTimeout(250);
const zoom2 = await d.locator('#map-zoom-level').textContent();
ok('map zoom controls work', parseFloat(zoom2) > 1.2, zoom2);
await d.keyboard.press('Escape');
await d.waitForTimeout(300);
ok('map closes with Escape', !(await d.evaluate(() => window.__game.mapOpen)));

// --- character switch ---
await d.keyboard.press('Tab');
await d.waitForTimeout(400);
ok('switch overlay opens', await d.locator('#switch-overlay:not(.hidden)').count() === 1);
await d.locator('.switch-card.carlos').click();
await d.waitForTimeout(1500);
const charInfo = await d.evaluate(() => ({ id: window.__game.player.charId, hud: document.getElementById('hud-name').textContent }));
ok('character switched to Carlos', charInfo.id === 'carlos', JSON.stringify(charInfo));

// --- save ---
await d.keyboard.press('Escape');
await d.waitForTimeout(300);
await d.locator('[data-pause="save"]').click();
await d.waitForTimeout(500);
const saved = await d.evaluate(() => !!localStorage.getItem('matteo5.save.v1'));
ok('save writes localStorage', saved);
await d.locator('[data-pause="resume"]').click();
await d.waitForTimeout(400);

// --- HUD screenshot at the pier ---
await d.evaluate(() => {
  const g = window.__game;
  g.player.pos.set(760, 0, 141); g.player.yaw = Math.PI / 2; g._camYaw = Math.PI / 2; g._camPitch = 0.06;
  g._placePlayer(); g._snapCamera();
});
await d.waitForTimeout(1200);
await d.screenshot({ path: `${out}/desktop-pier.png` });

// ================= MOBILE PORTRAIT =================
const m = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
attach(m, 'mobile');
await boot(m, { quality: 'low', resScale: 60, shadows: false, water: 'medium', distance: 65, showFps: false, touch: 'on' });
const mob = await m.evaluate(() => {
  const box = (id) => { const e = document.getElementById(id); const b = e.getBoundingClientRect(); return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height) }; };
  return {
    touchMode: document.body.classList.contains('touch-mode'),
    controls: !document.getElementById('touch-controls').classList.contains('hidden'),
    status: getComputedStyle(document.getElementById('mobile-status')).display,
    joystick: box('joystick'), actions: box('touch-actions'), objective: box('objective-panel'),
    minimap: box('minimap-wrap'), mapBtn: box('tbtn-map'), pauseBtn: box('tbtn-pause')
  };
});
ok('mobile touch mode + controls', mob.touchMode && mob.controls && mob.status === 'flex', JSON.stringify(mob));
const overlap = (a, b) => !(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y);
ok('objective does not overlap map buttons', !overlap(mob.objective, mob.mapBtn) && !overlap(mob.objective, mob.pauseBtn));
ok('minimap clear of objective', !overlap(mob.minimap, mob.objective), JSON.stringify({ mm: mob.minimap, obj: mob.objective }));
ok('touch actions fit on screen', mob.actions.x >= 0 && mob.actions.x + mob.actions.w <= 390 && mob.actions.y + mob.actions.h <= 844);

// joystick drag moves player
const p0 = await m.evaluate(() => ({ x: window.__game.player.pos.x, z: window.__game.player.pos.z }));
const jb = mob.joystick;
await m.mouse.move(jb.x + jb.w / 2, jb.y + jb.h / 2);
await m.mouse.down();
await m.mouse.move(jb.x + jb.w / 2, jb.y + jb.h / 2 - 42, { steps: 6 });
await m.waitForTimeout(900);
await m.mouse.up();
const p1 = await m.evaluate(() => ({ x: window.__game.player.pos.x, z: window.__game.player.pos.z }));
ok('virtual joystick moves player', Math.hypot(p1.x - p0.x, p1.z - p0.z) > 1, JSON.stringify({ p0, p1 }));

// camera drag on the right side
const yaw0 = await m.evaluate(() => window.__game._camYaw);
await m.mouse.move(300, 430);
await m.mouse.down();
await m.mouse.move(220, 430, { steps: 8 });
await m.mouse.up();
const yaw1 = await m.evaluate(() => window.__game._camYaw);
ok('right-side drag turns camera', Math.abs(yaw1 - yaw0) > 0.05, `dy=${(yaw1 - yaw0).toFixed(3)}`);

// shoot tap decreases ammo
const mag0 = await m.evaluate(() => window.__game.player.weapon.mag);
const sb = await m.locator('[data-touch="shoot"]').boundingBox();
await m.touchscreen.tap(sb.x + sb.width / 2, sb.y + sb.height / 2);
await m.waitForTimeout(250);
const mag1 = await m.evaluate(() => window.__game.player.weapon.mag);
ok('touch shoot fires', mag1 < mag0 || (await m.evaluate(() => window.__game.player.weapon.reserve)) < 48, `${mag0} -> ${mag1}`);
await m.waitForTimeout(600);
await m.screenshot({ path: `${out}/mobile-portrait.png` });

// mobile map + pause
await m.locator('#tbtn-map').click();
await m.waitForTimeout(500);
ok('mobile map opens', await m.evaluate(() => window.__game.mapOpen));
await m.screenshot({ path: `${out}/mobile-map.png` });
await m.locator('#map-overlay [data-close="map-overlay"]').first().click();
await m.waitForTimeout(300);
await m.locator('#tbtn-pause').click();
await m.waitForTimeout(400);
ok('mobile pause opens', await m.locator('#pause-menu:not(.hidden)').count() === 1);
await m.locator('[data-pause="settings"]').click();
await m.waitForTimeout(350);
await m.locator('#settings-tabs [data-tab="controls"]').click();
await m.waitForTimeout(200);
await m.screenshot({ path: `${out}/mobile-settings.png` });
