.crosshair.aiming span:nth-child(3),.crosshair.aiming span:nth-child(4){height:1px;width:8px}
.hitmarker{position:absolute;left:50%;top:50%;width:22px;height:22px;transform:translate(-50%,-50%) rotate(45deg);opacity:0;pointer-events:none}
.hitmarker:before,.hitmarker:after{content:"";position:absolute;background:#fff;box-shadow:0 0 5px rgba(255,80,80,.8)}
