  body.touch-mode .objective-panel{width:170px;padding:7px 9px}
  body.touch-mode .joystick{width:100px;height:100px;left:calc(12px + env(safe-area-inset-left));bottom:calc(10px + env(safe-area-inset-bottom))}
  body.touch-mode .touch-actions{--touch-base:.84;right:calc(6px + env(safe-area-inset-right));bottom:calc(6px + env(safe-area-inset-bottom))}
  body.touch-mode .dialogue{bottom:calc(8px + env(safe-area-inset-bottom));width:min(600px,56vw);padding:8px 10px}
  body.touch-mode .dlg-portrait{width:48px;height:58px}
  body.touch-mode .dlg-pt{font-size:9.5px}
  body.touch-mode .dlg-en{font-size:7px}
  body.touch-mode .subtitle{bottom:calc(96px + env(safe-area-inset-bottom))}
  body.touch-mode .interact-prompt{bottom:calc(118px + env(safe-area-inset-bottom))}
  body.touch-mode .touch-brand{display:none}
  body.touch-mode .touch-look-hint{display:none}
  body.touch-mode .tutorial{bottom:calc(120px + env(safe-area-inset-bottom));left:auto;right:12px;width:300px}
}
@media (prefers-reduced-motion:reduce){
  *,*:before,*:after{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important}
}

