3. Touch action handler. Replace the action block. Need exact old text. We saw it. We'll replace from `if (action === 'aim')` through `if (action === 'switch')...`.

New:
```js
        const p = this.player;
        if (action === 'aim') {
          if (p && p.inVehicle) { this.input.brake = true; this._haptic(8); return; }
          this.input.aim = true; this._haptic(8); return;
        }
        if (action === 'shoot') {
          if (p && p.inVehicle) { this.input.throttle = true; this._haptic(10); return; }
          this.input.aim = true;
          this._shoot();
          this._haptic(14);
          stopFire();
          const rate = Math.max(90, (this.player?.weapon?.fireRate || 0.26) * 1000);
          this._touchFireTimer = setInterval(() => {
            if (!this.paused && !this.dialogueActive && this.mode !== 'attract') this._shoot();
          }, rate);
          return;
        }
        if (action === 'sprint') {
          if (p && p.inVehicle) { this.audio.play('horn'); this._haptic(10); return; }
          this.input.sprint = true; this._haptic(6); return;
        }
        if (action === 'interact') { this._interact(); this._haptic(8); }
        if (action === 'melee') {
          if (p && p.inVehicle) { this.audio.play('horn'); this._haptic(10); return; }
          this._melee(); this._haptic(12);
        }
        if (action === 'jump') {
          if (p && p.inVehicle) { this.input.handbrake = true; this._haptic(8); return; }
          this._jump(); this._haptic(8);
        }
        if (action === 'switch') { this.openSwitch(); this._haptic(8); }
