import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/node_modules/playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/mhud';
mkdirSync(out, { recursive: true });
const URL = 'http://127.0.0.1:4173/';
const browser = await chromium.launch({
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist']
});
const page = await browser.newPage({
  viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2
});
page.setDefaultTimeout(90000);
page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0, 300)); });
await page.addInitScript(() => {
  localStorage.setItem('matteo5.settings.v1', JSON.stringify({
    quality: 'low', resScale: 55, shadows: false, water: 'low', distance: 60, touch: 'on'
  }));
  localStorage.removeItem('matteo5.save.v1');
});
await page.goto(URL, { waitUntil: 'load' });
await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
await page.locator('[data-menu="play"]').click();
await page.waitForTimeout(300);
await page.locator('.cs-card.luiza').click();
await page.waitForTimeout(2600);
await page.locator('#tut-start').click().catch(() => {});
await page.waitForTimeout(800);

const info = await page.evaluate(() => {
  const g = window.__game;
  const box = (sel) => {
    const e = document.querySelector(sel);
    if (!e) return null;
    const b = e.getBoundingClientRect();
    const cs = getComputedStyle(e);
    return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), display: cs.display, opacity: cs.opacity };
  };
  return {
    touchMode: document.body.classList.contains('touch-mode'),
    mobileHud: box('#mobile-hud'),
    compass: box('#mh-compass'),
    left: box('.mh-left'),
    status: box('#mobile-status'),
    context: box('#mh-context'),
    contextVehicle: document.getElementById('mh-context').classList.contains('vehicle'),
    weapon: box('#mh-weapon'),
    vehicle: box('#mh-vehicle'),
    minimap: box('#minimap-wrap'),
    objective: box('#objective-panel'),
    mapBtn: box('#tbtn-map'),
    joystick: box('#joystick'),
    actions: box('#touch-actions'),
    weaponName: document.getElementById('mh-weapon-name').textContent,
    ammo: document.getElementById('mh-ammo').textContent,
    labels: [...document.querySelectorAll('[data-touch]')].map(b => ({ a: b.dataset.touch, t: b.querySelector('small').textContent })),
    player: g ? { x: g.player.pos.x, z: g.player.pos.z } : null
  };
});
console.log(JSON.stringify(info, null, 1));
await page.screenshot({ path: `${out}/mobile-hud-onfoot.png` });

// Walk toward a vehicle and enter it programmatically through the real API.
const veh = await page.evaluate(() => {
  const g = window.__game;
  const v = g.vehicles.find(x => !x.isBoat && !x.destroyed && x.driver !== 'ai' && x.driver !== 'police');
  if (!v) return null;
  g.player.pos.set(v.pos.x + 1, g.world.groundHeight(v.pos.x + 1, v.pos.z), v.pos.z);
  g._placePlayer();
  g._enterVehicle(v);
  return { name: v.name, type: v.type, x: v.pos.x, z: v.pos.z };
});
console.log('VEHICLE', JSON.stringify(veh));
await page.waitForTimeout(600);
const drive = await page.evaluate(() => {
  const g = window.__game;
  return {
    inVehicle: !!g.player.inVehicle,
    contextVehicle: document.getElementById('mh-context').classList.contains('vehicle'),
    weaponDisplay: getComputedStyle(document.getElementById('mh-weapon')).display,
    vehicleDisplay: getComputedStyle(document.getElementById('mh-vehicle')).display,
    vehicleName: document.getElementById('mh-vehicle-name').textContent,
    speed: document.getElementById('mh-speed-val').textContent,
    gear: document.getElementById('mh-gear').textContent,
    labels: [...document.querySelectorAll('[data-touch]')].map(b => ({ a: b.dataset.touch, t: b.querySelector('small').textContent })),
    touchVehicle: document.getElementById('touch-controls').classList.contains('vehicle-mode')
  };
});
console.log('DRIVE', JSON.stringify(drive, null, 1));
await page.screenshot({ path: `${out}/mobile-hud-vehicle.png` });

// Hold the R2 accelerator button through a real touch pointer.
const r2 = await page.locator('[data-touch="shoot"]').boundingBox();
await page.evaluate(({ x, y }) => {
  const btn = document.querySelector('[data-touch="shoot"]');
  const base = { pointerId: 90, pointerType: 'touch', isPrimary: true, bubbles: true, clientX: x, clientY: y };
  btn.dispatchEvent(new PointerEvent('pointerdown', base));
}, { x: r2.x + r2.width / 2, y: r2.y + r2.height / 2 });
await page.waitForTimeout(1400);
const speed = await page.evaluate(() => {
  const g = window.__game;
  return { speed: g.player.inVehicle?.speed ?? 0, hud: document.getElementById('mh-speed-val').textContent, throttle: g.input.throttle };
});
await page.evaluate(({ x, y }) => {
  const btn = document.querySelector('[data-touch="shoot"]');
  const base = { pointerId: 90, pointerType: 'touch', isPrimary: true, bubbles: true, clientX: x, clientY: y };
  btn.dispatchEvent(new PointerEvent('pointerup', base));
}, { x: r2.x + r2.width / 2, y: r2.y + r2.height / 2 });
console.log('ACCEL', JSON.stringify(speed));

// Low health pulse + wanted state.
await page.evaluate(() => {
  const g = window.__game;
  g.player.health = 22;
  g.setWanted(4, true);
});
await page.waitForTimeout(400);
console.log('STATES', await page.evaluate(() => ({
  low: document.body.classList.contains('low-health'),
  wanted: document.body.classList.contains('high-wanted'),
  stars: document.querySelectorAll('#wanted-stars svg.on').length
})));
await page.screenshot({ path: `${out}/mobile-hud-damage.png` });

await browser.close();
console.log('DONE');

