import { createRequire } from 'node:module';
import { mkdirSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/node_modules/playwright/package.json');
const { chromium } = require('playwright');
const out = '/tmp/opencode/mhud2';
mkdirSync(out, { recursive: true });
const URL = 'http://127.0.0.1:4173/';
const browser = await chromium.launch({
  headless: true,
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist']
});

const ok = (name, cond, extra = '') => console.log(`${cond ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

async function boot(page, settings) {
  page.setDefaultTimeout(90000);
  page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
  page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0, 300)); });
  await page.addInitScript((s) => {
    localStorage.setItem('matteo5.settings.v1', JSON.stringify(s));
    localStorage.removeItem('matteo5.save.v1');
  }, settings);
  await page.goto(URL, { waitUntil: 'load' });
  await page.locator('#main-menu:not(.hidden)').waitFor({ state: 'visible' });
  await page.locator('[data-menu="play"]').click();
  await page.waitForTimeout(250);
  await page.locator('.cs-card.luiza').click();
  await page.waitForTimeout(2400);
  await page.locator('#tut-start').click().catch(() => {});
  await page.waitForTimeout(700);
}

const box = (page, sel) => page.evaluate((s) => {
  const e = document.querySelector(s);
  if (!e) return null;
  const b = e.getBoundingClientRect();
  const cs = getComputedStyle(e);
  return { x: Math.round(b.x), y: Math.round(b.y), w: Math.round(b.width), h: Math.round(b.height), display: cs.display, opacity: cs.opacity };
}, sel);
const overlap = (a, b) => a && b && !(a.x + a.w <= b.x || b.x + b.w <= a.x || a.y + a.h <= b.y || b.y + b.h <= a.y);

// ---------------- PORTRAIT 390 ----------------
const p = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await boot(p, { quality: 'low', resScale: 55, shadows: false, water: 'low', distance: 60, touch: 'auto' });
ok('touch HUD active with auto setting', await p.evaluate(() => document.body.classList.contains('touch-mode')));
const layout = await p.evaluate(() => {
  const b = (s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
  return {
    compass: b('#mh-compass'), minimap: b('#minimap-wrap'), mapBtn: b('#tbtn-map'),
    left: b('.mh-left'), status: b('#mobile-status'), context: b('#mh-context'),
    objective: b('#objective-panel'), joystick: b('#joystick'), actions: b('#touch-actions')
  };
});
ok('compass sits between minimap and map buttons', !overlap(layout.compass, layout.minimap) && !overlap(layout.compass, layout.mapBtn), JSON.stringify(layout.compass));
ok('left stack clear of objective', !overlap(layout.left, layout.objective), JSON.stringify({ left: layout.left, obj: layout.objective }));
ok('left stack clear of joystick', !overlap(layout.left, layout.joystick));
ok('context clear of touch actions', !overlap(layout.context, layout.actions));
await p.screenshot({ path: `${out}/portrait-onfoot.png` });

// Reload button
await p.evaluate(() => { window.__game.player.weapon.mag = 3; window.__game.player.reloading = 0; });
const rl = await p.locator('#mh-reload').boundingBox();
await p.touchscreen.tap(rl.x + rl.width / 2, rl.y + rl.height / 2);
await p.waitForTimeout(150);
ok('mobile reload button starts reload', await p.evaluate(() => window.__game.player.reloading > 0));
await p.waitForTimeout(1400);
ok('mobile reload refills magazine', await p.evaluate(() => window.__game.player.weapon.mag === 12));

// Enter vehicle through the real API
const veh = await p.evaluate(() => {
  const g = window.__game;
  const v = g.vehicles.find(x => !x.isBoat && !x.destroyed && x.driver !== 'ai' && x.driver !== 'police');
  if (!v) return null;
  g.player.pos.set(v.pos.x + 1, g.world.groundHeight(v.pos.x + 1, v.pos.z), v.pos.z);
  g._placePlayer();
  g._enterVehicle(v);
  return { name: v.name, x: v.pos.x, z: v.pos.z };
});
ok('entered a vehicle', !!veh, JSON.stringify(veh));
await p.waitForTimeout(500);
const driving = await p.evaluate(() => ({
  ctx: document.getElementById('mh-context').classList.contains('vehicle'),
  weapon: getComputedStyle(document.getElementById('mh-weapon')).display,
  vehicle: getComputedStyle(document.getElementById('mh-vehicle')).display,
  labels: Object.fromEntries([...document.querySelectorAll('[data-touch]')].map(b => [b.dataset.touch, b.querySelector('small').textContent]))
}));
ok('context card switches to vehicle', driving.ctx && driving.weapon === 'none' && driving.vehicle === 'flex', JSON.stringify(driving));
ok('touch labels switch to vehicle', driving.labels.shoot === 'ACELERAR' && driving.labels.interact === 'SAIR' && driving.labels.jump === 'FREIO MÃO');
await p.screenshot({ path: `${out}/portrait-vehicle.png` });

// Accelerator + brake through pointer events
const r2 = await p.locator('[data-touch="shoot"]').boundingBox();
const press = (sel, id) => p.evaluate(({ sel, id }) => {
  const b = document.querySelector(sel).getBoundingClientRect();
  const base = { pointerId: id, pointerType: 'touch', isPrimary: true, bubbles: true, clientX: b.x + b.width / 2, clientY: b.y + b.height / 2 };
  document.querySelector(sel).dispatchEvent(new PointerEvent('pointerdown', base));
}, { sel, id });
const release = (sel, id) => p.evaluate(({ sel, id }) => {
  const b = document.querySelector(sel).getBoundingClientRect();
  const base = { pointerId: id, pointerType: 'touch', isPrimary: true, bubbles: true, clientX: b.x + b.width / 2, clientY: b.y + b.height / 2 };
  document.querySelector(sel).dispatchEvent(new PointerEvent('pointerup', base));
}, { sel, id });
await press('[data-touch="shoot"]', 90);
await p.waitForTimeout(1200);
const accel = await p.evaluate(() => ({ speed: window.__game.player.inVehicle?.speed || 0, throttle: window.__game.input.throttle }));
ok('R2 accelerates the car', accel.speed > 3 && accel.throttle, JSON.stringify(accel));
await release('[data-touch="shoot"]', 90);
await press('[data-touch="aim"]', 91);
await p.waitForTimeout(800);
const brake = await p.evaluate(() => ({ speed: window.__game.player.inVehicle?.speed || 0, brake: window.__game.input.brake }));
ok('L2 brakes the car', brake.speed < accel.speed && brake.brake, JSON.stringify(brake));
await release('[data-touch="aim"]', 91);

// Toast placement
await p.evaluate(() => window.__game.notify('TESTE', 'Notificação do HUD mobile.', 'good'));
await p.waitForTimeout(350);
const toast = await box(p, '#toast-layer .toast');
const objective = await box(p, '#objective-panel');
const leftStack = await box(p, '.mh-left');
ok('mobile toast does not cover objective', !overlap(toast, objective), JSON.stringify({ toast, objective }));
ok('mobile toast does not cover left stack', !overlap(toast, leftStack), JSON.stringify({ toast, leftStack }));
await p.screenshot({ path: `${out}/portrait-toast.png` });

// Exit vehicle restores labels
await p.evaluate(() => window.__game._exitVehicle());
await p.waitForTimeout(400);
const back = await p.evaluate(() => ({
  ctx: document.getElementById('mh-context').classList.contains('vehicle'),
  labels: Object.fromEntries([...document.querySelectorAll('[data-touch]')].map(b => [b.dataset.touch, b.querySelector('small').textContent]))
}));
ok('exit restores on-foot HUD', !back.ctx && back.labels.shoot === 'ATIRAR' && back.labels.jump === 'PULAR', JSON.stringify(back));

// Low health overlay is behind HUD text (z-order check via screenshot + class)
await p.evaluate(() => { window.__game.player.health = 20; });
await p.waitForTimeout(400);
ok('low health state toggles', await p.evaluate(() => document.body.classList.contains('low-health')));
await p.screenshot({ path: `${out}/portrait-low-health.png` });

// ---------------- NARROW 320 ----------------
const n = await browser.newPage({ viewport: { width: 320, height: 720 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await boot(n, { quality: 'low', resScale: 50, shadows: false, water: 'low', distance: 55, touch: 'on' });
const nl = await n.evaluate(() => {
  const b = (s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
  return { compass: b('#mh-compass'), minimap: b('#minimap-wrap'), mapBtn: b('#tbtn-map'), left: b('.mh-left'), objective: b('#objective-panel'), actions: b('#touch-actions'), joystick: b('#joystick') };
});
ok('320px compass clear of minimap/buttons', !overlap(nl.compass, nl.minimap) && !overlap(nl.compass, nl.mapBtn), JSON.stringify(nl.compass));
ok('320px left stack clear of objective', !overlap(nl.left, nl.objective), JSON.stringify({ left: nl.left, obj: nl.objective }));
ok('320px touch actions fit', nl.actions.x >= 0 && nl.actions.x + nl.actions.w <= 320 && nl.actions.y + nl.actions.h <= 720, JSON.stringify(nl.actions));
await n.screenshot({ path: `${out}/narrow-onfoot.png` });

// ---------------- LANDSCAPE 844x390 ----------------
const l = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await boot(l, { quality: 'low', resScale: 55, shadows: false, water: 'low', distance: 60, touch: 'on' });
const ll = await l.evaluate(() => {
  const b = (s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
  return { left: b('.mh-left'), context: b('#mh-context'), objective: b('#objective-panel'), joystick: b('#joystick'), actions: b('#touch-actions'), compass: b('#mh-compass') };
});
ok('landscape left stack clear of objective', !overlap(ll.left, ll.objective), JSON.stringify({ left: ll.left, obj: ll.objective }));
ok('landscape left stack clear of joystick', !overlap(ll.left, ll.joystick), JSON.stringify({ left: ll.left, joy: ll.joystick }));
ok('landscape context clear of actions', !overlap(ll.context, ll.actions), JSON.stringify({ ctx: ll.context, act: ll.actions }));
await l.evaluate(() => window.__game.notify('TESTE', 'Notificação no modo paisagem.', 'good'));
await l.waitForTimeout(350);
const ltoast = await box(l, '#toast-layer .toast');
const lobj = await box(l, '#objective-panel');
const lact = await box(l, '#touch-actions');
ok('landscape toast clear of objective/actions', !overlap(ltoast, lobj) && !overlap(ltoast, lact), JSON.stringify({ toast: ltoast, obj: lobj, act: lact }));
await l.screenshot({ path: `${out}/landscape-onfoot.png` });

// ---------------- TABLET 768 ----------------
const t = await browser.newPage({ viewport: { width: 768, height: 1024 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 });
await boot(t, { quality: 'low', resScale: 60, shadows: false, water: 'low', distance: 60, touch: 'auto' });
ok('tablet touch HUD active', await t.evaluate(() => document.body.classList.contains('touch-mode')));
const tl = await t.evaluate(() => {
  const b = (s) => { const e = document.querySelector(s); if (!e) return null; const r = e.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
  return { left: b('.mh-left'), objective: b('#objective-panel'), compass: b('#mh-compass'), minimap: b('#minimap-wrap'), actions: b('#touch-actions'), joystick: b('#joystick') };
});
ok('tablet left stack clear of objective', !overlap(tl.left, tl.objective), JSON.stringify({ left: tl.left, obj: tl.objective }));
ok('tablet compass clear of minimap', !overlap(tl.compass, tl.minimap), JSON.stringify({ c: tl.compass, m: tl.minimap }));
await t.screenshot({ path: `${out}/tablet-onfoot.png` });

await browser.close();
console.log('DONE');

