import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/node_modules/playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-webgl','--ignore-gpu-blocklist'] });
const ok = (n,c,e='') => console.log(`${c?'PASS':'FAIL'} ${n}${e?' — '+e:''}`);
const errors = [];
async function boot(page, settings) {
  page.setDefaultTimeout(90000);
  page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
  page.on('console', m => { if (m.type()==='error') { errors.push(m.text()); console.log('CONSOLE', m.text().slice(0,200)); } });
  await page.addInitScript((s) => { localStorage.setItem('matteo5.settings.v1', JSON.stringify(s)); localStorage.removeItem('matteo5.save.v1'); }, settings);
  await page.goto('http://127.0.0.1:4173/', {waitUntil:'load'});
  await page.locator('#main-menu:not(.hidden)').waitFor({state:'visible'});
  await page.locator('[data-menu="play"]').click();
  await page.waitForTimeout(250);
  await page.locator('.cs-card.luiza').click();
  await page.waitForTimeout(2500);
  await page.locator('#tut-start').click().catch(()=>{});
  await page.waitForTimeout(700);
}
const m = await browser.newPage({ viewport:{width:390,height:844}, isMobile:true, hasTouch:true, deviceScaleFactor:2 });
await boot(m, {quality:'low',resScale:55,shadows:false,water:'low',distance:60,touch:'auto'});
ok('mobile HUD visible', await m.evaluate(() => document.body.classList.contains('touch-mode') && getComputedStyle(document.getElementById('mobile-hud')).display === 'block'));
ok('mobile HUD cards populated', await m.evaluate(() => document.getElementById('mh-weapon-name').textContent.includes('PISTOLA') && document.getElementById('mh-ammo').textContent === '12'));
// map + pause + settings
await m.locator('#tbtn-map').click(); await m.waitForTimeout(500);
ok('mobile map opens', await m.evaluate(() => window.__game.mapOpen));
await m.locator('#map-overlay [data-close="map-overlay"]').first().click(); await m.waitForTimeout(300);
ok('mobile map closes and releases lock', await m.evaluate(() => !window.__game.mapOpen));
await m.locator('#tbtn-pause').click(); await m.waitForTimeout(400);
ok('mobile pause opens', await m.locator('#pause-menu:not(.hidden)').count() === 1);
await m.locator('[data-pause="settings"]').click(); await m.waitForTimeout(350);
ok('mobile settings above pause', await m.evaluate(() => {
  const s = document.getElementById('settings-modal'), p = document.getElementById('pause-menu');
  return !s.classList.contains('hidden') && +getComputedStyle(s).zIndex > +getComputedStyle(p).zIndex;
}));
await m.locator('#settings-modal [data-close="settings-modal"]').first().click();
await m.locator('[data-pause="resume"]').click(); await m.waitForTimeout(400);
ok('mobile resume works', await m.evaluate(() => !window.__game.paused));
// vehicle flow
const v = await m.evaluate(() => {
  const g = window.__game; const v = g.vehicles.find(x => !x.isBoat && !x.destroyed);
  g.player.pos.set(v.pos.x + 1, g.world.groundHeight(v.pos.x + 1, v.pos.z), v.pos.z); g._placePlayer(); g._enterVehicle(v);
  return v.name;
});
await m.waitForTimeout(400);
ok('mobile vehicle card + labels', await m.evaluate(() => document.getElementById('mh-context').classList.contains('vehicle') && document.querySelector('[data-touch="shoot"] small').textContent === 'ACELERAR' && document.querySelector('[data-touch="sprint"] small').textContent === 'TURBO'), v);
await m.evaluate(() => window.__game._exitVehicle()); await m.waitForTimeout(300);
ok('mobile on-foot restore', await m.evaluate(() => !document.getElementById('mh-context').classList.contains('vehicle') && document.querySelector('[data-touch="shoot"] small').textContent === 'ATIRAR'));
// desktop
const d = await browser.newPage({ viewport:{width:1440,height:900} });
await boot(d, {quality:'low',resScale:70,shadows:false,water:'low',distance:70,touch:'off'});
ok('desktop HUD unaffected', await d.evaluate(() => !document.body.classList.contains('touch-mode') && getComputedStyle(document.getElementById('mobile-hud')).display === 'none'));
await d.keyboard.press('KeyM'); await d.waitForTimeout(500);
ok('desktop map opens', await d.evaluate(() => window.__game.mapOpen));
await d.keyboard.press('Escape'); await d.waitForTimeout(300);
ok('desktop map closes', await d.evaluate(() => !window.__game.mapOpen));
ok('no page errors', errors.length === 0, errors.slice(0,3).join(' | '));
await browser.close();
console.log('DONE');
EOF
